using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace EALRMS.Models;

/// <summary>
/// Represents a software application managed within the enterprise inventory.
/// This entity maps directly to the "Applications" table in PostgreSQL.
/// </summary>
public class Application
{
    /// <summary>
    /// Unique identifier for the application record.
    /// Configured as an auto-incrementing primary key generated by the database.
    /// </summary>
    [Key]
    [DatabaseGenerated(DatabaseGeneratedOption.Identity)]
    [Display(Name = "Application ID")]
    public int Id { get; set; }

    /// <summary>
    /// The display name of the application (e.g., "Customer Portal", "Billing API").
    /// Required because every enterprise application must have an identifiable title.
    /// </summary>
    [Required(ErrorMessage = "Application name is required.")]
    [StringLength(100, ErrorMessage = "Application name cannot exceed 100 characters.")]
    [Display(Name = "Application Name")]
    public string Name { get; set; } = string.Empty;

    /// <summary>
    /// A summary of the application's purpose and functionality.
    /// Optional field to help team members understand what the application does.
    /// </summary>
    [StringLength(500, ErrorMessage = "Description cannot exceed 500 characters.")]
    [Display(Name = "Description")]
    public string? Description { get; set; }

    /// <summary>
    /// The primary framework, language, or platform (e.g., ".NET 10", "React", "Python").
    /// Required so engineering leaders know the underlying technology stack.
    /// </summary>
    [Required(ErrorMessage = "Primary technology stack is required.")]
    [StringLength(100, ErrorMessage = "Technology cannot exceed 100 characters.")]
    [Display(Name = "Technology Stack")]
    public string Technology { get; set; } = string.Empty;

    /// <summary>
    /// The current deployed semantic or release version (e.g., "1.0.0", "2.4-beta").
    /// Optional field because early-stage or internal applications might not yet be versioned.
    /// </summary>
    [StringLength(30, ErrorMessage = "Version cannot exceed 30 characters.")]
    [Display(Name = "Current Version")]
    public string? Version { get; set; }

    /// <summary>
    /// Operational status of the application. Must be either 'Active' or 'Inactive'.
    /// Indicates whether the application is currently live in production or decommissioned.
    /// </summary>
    [Required(ErrorMessage = "Status is required.")]
    [RegularExpression("^(Active|Inactive)$", ErrorMessage = "Status must be either 'Active' or 'Inactive'.")]
    [Display(Name = "Lifecycle Status")]
    public string Status { get; set; } = "Active";

    /// <summary>
    /// Timestamp when this application was registered in the inventory (in UTC).
    /// System-managed to maintain a reliable audit trail; users cannot manually alter this.
    /// </summary>
    [Display(Name = "Created At (UTC)")]
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

    /// <summary>
    /// Timestamp when this application was last modified (in UTC).
    /// Nullable because freshly registered applications have not yet been updated.
    /// </summary>
    [Display(Name = "Last Updated (UTC)")]
    public DateTime? UpdatedAt { get; set; }
}
